      const line = (a0, r0, a1, r1, hot) => { const p = P(a0, r0), q = P(a1, r1), n = Math.ceil(Math.hypot(q[0] - p[0], q[1] - p[1]) / 1.5); for (let i = 0; i <= n; i++) { const f = i / n; dot(p[0] + (q[0] - p[0]) * f, p[1] + (q[1] - p[1]) * f, col(a0 + (a1 - a0) * f, hot)); } };
