        for (let i = 0; i < wk; i++) { const sx = side ? (Gt.LW - wk) + Math.floor(i * Gt.LW / wk) - (Gt.LW - wk) : Math.floor(i * Gt.LW / wk); ctx.drawImage(src, Math.min(Gt.LW - 1, Math.max(0, sx)), 0, 1, Gt.h, lx + i * CS, y0, CS, Gt.h * CS); }
