          if (t > TL.fly[i] && t < TL.fly[i] + TL.flyDur + 0.25) for (let k = 1; k <= 4; k++) { const q = shardPos(R, i, t - k * 0.07); if (!q) continue; ctx.fillStyle = k % 2 ? GEM[i].c : '#ffffff'; ctx.fillRect(snap2(q[0] + (hash(k + i * 9) - 0.5) * 8), snap2(q[1] + (hash(k * 3 + i) - 0.5) * 8), 2, 2); }
          if (Math.floor(t / 0.2) % 2 === 0) blit(C.glow[i], ox, oy);
